module traveling_salesman (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [3:0] m,\n    input wire [3:0] edges_a [0:7],\n    input wire [3:0] edges_b [0:7],\n    input wire [7:0] valid_edges,\n    output reg [7:0] flights,\n    output reg [7:0] airports,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE             = 4'd0;\n    localparam [3:0] READ_EDGES       = 4'd1;\n    localparam [3:0] COMPUTE_MAX      = 4'd2;\n    localparam [3:0] COMPUTE_L_UNMATCH = 4'd3;\n    localparam [3:0] COMPUTE_R_UNMATCH = 4'd4;\n    localparam [3:0] OUTPUT_RESULTS   = 4'd5;\n    localparam [3:0] DONE_STATE       = 4'd6;\n    \n    reg [3:0] state, next_state;\n    reg [3:0] stored_n;\n    reg [3:0] stored_m;\n    reg [3:0] edges_a_reg[0:7];\n    reg [3:0] edges_b_reg[0:7];\n    reg [7:0] valid_edges_reg;\n    \n    // Maximum matching globals\n    reg [7:0] global_max;\n    reg [7:0] current_city_index;\n    reg [7:0] current_side;\n    reg [7:0] current_max;\n    reg [7:0] temp_airports;\n    \n    // Computation registers\n    reg [8:0] subset;\n    reg [7:0] max_count;\n    reg [7:0] left_used;\n    reg [7:0] right_used;\n    reg [7:0] count;\n    reg [7:0] i;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            flights <= 8'd0;\n            airports <= 8'd0;\n            done <= 1'b0;\n            current_city_index <= 8'd0;\n            subset <= 9'd0;\n            temp_airports <= 8'd0;\n            valid_edges_reg <= 8'd0;\n            global_max <= 8'd0;\n            current_side <= 8'd0;\n            current_max <= 8'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                edges_a_reg[i] <= 4'd0;\n                edges_b_reg[i] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    flights <= 8'd0;\n                    airports <= 8'd0;\n                    temp_airports <= 8'd0;\n                    current_city_index <= 8'd1;\n                    current_side <= 8'd0;\n                    subset <= 9'd0;\n                    if (start) begin\n                        state <= READ_EDGES;\n                    end\n                end\n                \n                READ_EDGES: begin\n                    valid_edges_reg <= valid_edges;\n                    stored_n <= n;\n                    stored_m <= m;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        edges_a_reg[i] <= edges_a[i];\n                        edges_b_reg[i] <= edges_b[i];\n                    end\n                    global_max <= 8'd0;\n                    state <= COMPUTE_MAX;\n                end\n                \n                COMPUTE_MAX: begin\n                    // Compute maximum matching for global_max\n                    if (subset == (9'd1 << stored_m)) begin\n                        state <= COMPUTE_L_UNMATCH;\n                        subset <= 9'd0;\n                        flights <= (stored_n > 1) ? stored_n - global_max - 8'd1 : 8'd0;\n                    end else begin\n                        left_used <= 8'd0;\n                        right_used <= 8'd0;\n                        count <= 8'd0;\n                        \n                        // Check subset validity\n                        for (i = 0; i < stored_m; i = i + 1) begin\n                            if (subset[i] && valid_edges_reg[i]) begin\n                                if (left_used[edges_a_reg[i]-1] || right_used[edges_b_reg[i]-1]) begin\n                                    count <= 8'd0;\n                                    i <= stored_m; // break;\n                                end else begin\n                                    left_used[edges_a_reg[i]-1] <= 1'b1;\n                                    right_used[edges_b_reg[i]-1] <= 1'b1;\n                                    count <= count + 8'd1;\n                                end\n                            end\n                        end\n                        \n                        if (count > global_max) begin\n                            global_max <= count;\n                        end\n                        subset <= subset + 9'd1;\n                    end\n                end\n                \n                COMPUTE_L_UNMATCH: begin\n                    // Check if city current_city_index can be unmatched on left\n                    if (current_city_index > stored_n) begin\n                        current_side <= 8'd1;\n                        current_city_index <= 8'd1;\n                        state <= COMPUTE_R_UNMATCH;\n                    end else begin\n                        if (subset == (9'd1 << stored_m)) begin\n                            current_max <= 8'd0;\n                            if (global_max == current_max) begin\n                                temp_airports[current_city_index-1] <= 1'b1;\n                            end\n                            current_city_index <= current_city_index + 8'd1;\n                            subset <= 9'd0;\n                        end else begin\n                            left_used <= 8'd0;\n                            right_used <= 8'd0;\n                            count <= 8'd0;\n                            \n                            for (i = 0; i < stored_m; i = i + 1) begin\n                                if (subset[i] && valid_edges_reg[i]) begin\n                                    if (edges_a_reg[i] == current_city_index || \n                                        left_used[edges_a_reg[i]-1] || \n                                        right_used[edges_b_reg[i]-1]) begin\n                                        count <= 8'd0;\n                                        i <= stored_m;\n                                    end else begin\n                                        left_used[edges_a_reg[i]-1] <= 1'b1;\n                                        right_used[edges_b_reg[i]-1] <= 1'b1;\n                                        count <= count + 8'd1;\n                                    end\n                                end\n                            end\n                            \n                            if (count > current_max) current_max <= count;\n                            subset <= subset + 9'd1;\n                        end\n                    end\n                end\n                \n                COMPUTE_R_UNMATCH: begin\n                    // Check if city current_city_index can be unmatched on right\n                    if (current_city_index > stored_n) begin\n                        state <= OUTPUT_RESULTS;\n                    end else begin\n                        if (subset == (9'd1 << stored_m)) begin\n                            current_max <= 8'd0;\n                            if (global_max == current_max) begin\n                                temp_airports[current_city_index-1] <= 1'b1;\n                            end\n                            current_city_index <= current_city_index + 8'd1;\n                            subset <= 9'd0;\n                        end else begin\n                            left_used <= 8'd0;\n                            right_used <= 8'd0;\n                            count <= 8'd0;\n                            \n                            for (i = 0; i < stored_m; i = i + 1) begin\n                                if (subset[i] && valid_edges_reg[i]) begin\n                                    if (edges_b_reg[i] == current_city_index || \n                                        left_used[edges_a_reg[i]-1] || \n                                        right_used[edges_b_reg[i]-1]) begin\n                                        count <= 8'd0;\n                                        i <= stored_m;\n                                    end else begin\n                                        left_used[edges_a_reg[i]-1] <= 1'b1;\n                                        right_used[edges_b_reg[i]-1] <= 1'b1;\n                                        count <= count + 8'd1;\n                                    end\n                                end\n                            end\n                            \n                            if (count > current_max) current_max <= count;\n                            subset <= subset + 9'd1;\n                        end\n                    end\n                end\n                \n                OUTPUT_RESULTS: begin\n                    airports <= temp_airports;\n                    state <= DONE_STATE;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule